# Code generated by Claude
"""Keyboard command source: turns the state of the keys into commands for the control loop.

This is the key handling of experiments/combined_controller.py (jog keys, pedestal keys and the cruise-control
drive ramp), moved here and turned into a source with step(obs) returning a list of commands. There is no other
logic.

    source = make_keyboard_source(model, held, drive_cfg, ped_step, ped_range, data=data, neck_specs=neck_specs)
    commands = source["step"](obs)

`held(key_code)` says whether a graphics library framework (GLFW) key is down (the real keyboard or the test key
injection set by CC_BENCH_KEYS); the launcher supplies it. On every tick the source reads the key state and returns
up to four commands (see src/commands.py):
  base      the drive ramp (arrows and the space bar) as a Twist, emitted while the ramp is not at rest or a drive key
            is down, and once more when the ramp reaches zero; so cruise control keeps the last speed after the keys
            are released, exactly as before
  pedestal  Page Up / Page Down: the applied height plus or minus one step, clipped to the pedestal range
  arms      jog keys: the applied joint and gripper targets plus or minus one step for each key held
  neck      jog keys 9 0 - = (plus) and O P [ ] (minus) for pan, lift, elbow and wrist; F7 frames the task points
            (src/neck_framing.py, when the scene has a task); F8 returns the neck to its default aim. None of these
            keys is used for anything else.
Targets are computed from obs["applied"] (what the loop currently holds), not from an internal integrator, so a command
that is held back by the hold rule does not wind up while it waits.
"""

import glfw
import numpy as np

JOG_JOINT_SPEED = 3.125   # rad/s while a jog key is held (the command moves this much per second of sim time, whatever the tick rate)
JOG_GRIP_SPEED = 0.1875   # m/s (finger travel is 0 closed .. 0.044 open)
GRIP_IDX = 7            # item 0-6 = joints 1-7, 7 = gripper

# One fixed key pair per joint, shoulder (j1) to wrist (j7) then gripper,
# left to right. The upper key increases, the lower key decreases (the
# gripper's upper key opens it). Left arm on the top two rows, right arm on
# the home and bottom rows.
JOG_KEYS = {
    "left":  {"plus":  ["1", "2", "3", "4", "5", "6", "7", "8"],
              "minus": ["Q", "W", "E", "R", "T", "Y", "U", "I"]},
    "right": {"plus":  ["A", "S", "D", "F", "G", "H", "J", "K"],
              "minus": ["Z", "X", "C", "V", "B", "N", "M", "COMMA"]},
}

# Pedestal lift (placeholder actuator, robot_specs.PEDESTAL_SPECS): Page Up raises, Page Down
# lowers while held. The command moves at jog_speed per second of SIM time (the launcher passes
# jog_speed * tick period as ped_step), so it does not depend on the viewer's frame rate.
PEDESTAL_KEYS = {"up": "PAGE_UP", "down": "PAGE_DOWN"}

# Camera neck: the same layout idea as the arms (plus on the upper row, minus below, one column per joint, shoulder to wrist)
NECK_KEYS = {"plus": ["9", "0", "MINUS", "EQUAL"], "minus": ["O", "P", "LEFT_BRACKET", "RIGHT_BRACKET"],
             "frame": "F7", "home": "F8"}

# Base drive keys and ramp (was CONTROL_GROUPS[0]["keys"] / ["drive_params"])
DRIVE_CFG = {
    "keys": {
        "forward":  ["UP"],
        "backward": ["DOWN"],
        "left":     ["LEFT"],
        "right":    ["RIGHT"],
        "stop":     ["SPACE"],
    },
    "drive_params": {
        "max_linear_vel":  1.5,   # m/s (real Tracer max ~1.6 m/s)
        "max_angular_vel": 2.0,   # rad/s
        "ramp_rate":       1.25,  # 1/s: change of the normalised command per second (full speed in 0.8 s). A gentle
                                   # ramp: a fast one flings the arms because velocity control decouples base from arm inertia
    },
}


def key_code(name: str) -> int:
    """Look up the graphics library framework (GLFW) key code of a key name.

    Args:
        name (str): Key name without the "KEY_" prefix, in any letter case,
            for example "up", "PAGE_UP" or "COMMA".

    Returns:
        int: The GLFW key code, glfw.KEY_<NAME>.

    Raises:
        ValueError: If GLFW has no key with that name.
    """
    val = getattr(glfw, f"KEY_{name.upper()}", None)
    if val is None:
        raise ValueError(f"Unknown GLFW key: {name}")
    return val


def build_jog_tables(model, mujoco):
    """Build the per-side tables of the eight jog items (seven arm joints and the gripper).

    Items 0-6 are arm joints 1-7; item 7 is the gripper, whose two fingers
    move together (0 = closed, 0.044 m = open on both hands).

    Args:
        model (mujoco.MjModel): The robot model. Must contain the actuators
            "<side>_joint<i>_ctrl" (i = 1..7) and "<side>_gripper_ctrl" for both sides.
        mujoco (module): The mujoco module (passed in by the caller).

    Returns:
        dict[str, list[tuple]]: Maps "left" and "right" to a list of 8 items.
        Each item is (actuator_ids, (lo, hi), speed): the list of actuator ids
        driven together (one for a joint, two for the gripper), the joint
        range in radians (metres for the gripper) taken from the first
        actuator's joint, and the jog speed (JOG_JOINT_SPEED radians per
        second or JOG_GRIP_SPEED metres per second).

    Raises:
        RuntimeError: If one of the actuators is not in the model.
    """
    def aid(name):
        a = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, name)
        if a < 0:
            raise RuntimeError(f"Actuator '{name}' not in model.")
        return a

    def jrange(a):
        return tuple(model.jnt_range[model.actuator_trnid[a, 0]])

    tables = {}
    for side in ("left", "right"):
        items = []
        for i in range(1, 8):
            a = aid(f"{side}_joint{i}_ctrl")
            items.append(([a], jrange(a), JOG_JOINT_SPEED))
        f = [aid(f"{side}_gripper_ctrl")]
        items.append((f, jrange(f[0]), JOG_GRIP_SPEED))
        tables[side] = items
    return tables


def make_keyboard_source(model, held, drive_cfg, ped_step, ped_range, data=None, neck_specs=None, points_fn=None, framing_cfg=None, neck_locked=False):
    """Create the keyboard source.

    Args:
        model (mujoco.MjModel): The robot model.
        held (Callable[[int], bool]): Takes a graphics library framework (GLFW)
            key code and returns whether that key is down.
        drive_cfg (dict | None): Base keys and ramp, shaped like DRIVE_CFG:
            {"keys": {"forward" | "backward" | "left" | "right" | "stop":
            [key names]}, "drive_params": {"max_linear_vel" (m/s, default 1.5),
            "max_angular_vel" (rad/s, default 2.0), "ramp_rate" (change of the
            normalised command per second, default 6.25)}}. None means no base
            keys.
        ped_step (float): Change of the pedestal height command per tick while
            a pedestal key is held, in metres (the caller multiplies the jog speed by the tick length).
        ped_range (tuple[float, float]): (lowest, highest) pedestal height
            command in metres.
        data (mujoco.MjData | None): Simulation state, needed only to frame the
            task points with F7. Defaults to None.
        neck_specs (dict | None): Neck settings (robot_specs.NECK_SPECS: joint
            names, "jog_speed" in radians per second, "drive_pose" in radians).
            None means no neck keys. Defaults to None.
        points_fn (Callable | None): Called as points_fn(model, data) and
            returns a dictionary of world points (metres) that F7 should frame,
            or an empty one if the scene has no task. Defaults to None (F7
            then reports that no task is loaded).
        framing_cfg (dict | None): Settings passed to
            src.neck_framing.frame_points when F7 is pressed. Defaults to None
            (an empty dictionary, so the framing defaults apply).
        neck_locked (bool): True while a replayable recording is being written (--record / --record-run): the neck keys (jog, F7, F8)
            do nothing and each key press prints one line saying so. The eagle camera is a policy input, so in a recorded run only the
            scripted framing may aim it. Defaults to False (the keys work).

    Returns:
        dict: The source, with these keys:
            "name" (str): "keyboard".
            "step" (Callable[[dict], list[dict]]): Takes the observation `obs`
                (uses obs["time"] and obs["applied"]) and returns this tick's
                commands (see step() inside this function).
            "state" (dict): Live state that other code reads. "drive" is the
                normalised drive command {"linear": float, "angular": float},
                each between -1 and 1. "was_moving" (bool) is whether the
                ramp was away from zero on the last tick. With a neck,
                "neck_active_t" is the simulated time in seconds of the last
                neck key press (-1e9 before any), which the automatic neck
                source reads, and "prev_f7" and "prev_f8" are the last key
                states of F7 and F8.

    Raises:
        ValueError: If a key name is not a GLFW key.
        RuntimeError: If an arm or finger actuator is missing from the model.
    """
    import mujoco
    drive_keys = {action: [key_code(k) for k in key_list] for action, key_list in (drive_cfg or {"keys": {}})["keys"].items()}
    for action in ("forward", "backward", "left", "right", "stop"):
        drive_keys.setdefault(action, [])
    dp = (drive_cfg or {}).get("drive_params", {})
    ramp_rate = dp.get("ramp_rate", 6.25)
    max_lin_vel = dp.get("max_linear_vel", 1.5)
    max_ang_vel = dp.get("max_angular_vel", 2.0)
    ds = {"linear": 0.0, "angular": 0.0}
    state = {"drive": ds, "was_moving": False}

    jog_tables = build_jog_tables(model, mujoco)
    jog_keymap = {side: list(zip([key_code(k) for k in kk["plus"]], [key_code(k) for k in kk["minus"]]))
                  for side, kk in JOG_KEYS.items()}
    ped_keys = {d: key_code(k) for d, k in PEDESTAL_KEYS.items()}
    ped_lo, ped_hi = ped_range

    # --- neck keys (only if the model has a neck) ---
    from src.neck import neck_ids
    nk = neck_ids(model, neck_specs) if neck_specs is not None else None
    if nk is not None:
        neck_pairs = list(zip([key_code(k) for k in NECK_KEYS["plus"]], [key_code(k) for k in NECK_KEYS["minus"]]))
        k_frame, k_home = key_code(NECK_KEYS["frame"]), key_code(NECK_KEYS["home"])
        state.update(neck_active_t=-1e9, prev_f7=False, prev_f8=False, prev_neck_locked_press=frozenset())

    def step(obs):
        """Read the keys and return this tick's commands.

        Ramps the drive command, then looks at the pedestal, jog and neck keys.
        Changes the enclosing scope's drive state `ds` and `state` (the ramp
        values, "was_moving", and the neck key times and edge flags). Prints a
        message when F7 is pressed.

        Args:
            obs (dict): Observation from the control loop. Uses:
                "time" (float): Simulated time in seconds.
                "timestep" and "steps_per_frame": the tick length in seconds is their product; the per-second jog speeds and the
                  drive ramp rate are multiplied by it.
                "applied" (dict): The targets the loop holds: "pedestal"
                  (height in metres), "arm_targets" ({side: 7 joint angles in
                  radians}), "gripper" ({side: finger travel in metres}) and,
                  with a neck, "neck_goal" ({joint name: radians}).

        Returns:
            list[dict]: Zero or more commands:
                {"mode": "base", "twist": (linear m/s, angular rad/s)}
                {"mode": "pedestal", "height": float metres}
                {"mode": "arms", "arm_targets": {side: [7 radians]},
                  "gripper": {side: metres}} (either entry may be missing;
                  only the sides with a key held are included)
                {"mode": "neck", "neck_targets": {joint name: radians}}
                  (up to three of these: jog, F7 framing and F8 home)
        """
        applied = obs["applied"]
        cmds = []
        dt = obs["timestep"] * obs["steps_per_frame"]
        incr = ramp_rate * dt

        # --- Drive: ramp linear/angular commands (cruise control) ---
        drive_key_down = any(held(k) for ks in drive_keys.values() for k in ks)
        ds["linear"] += (incr if any(held(k) for k in drive_keys["forward"]) else 0.0) \
                      - (incr if any(held(k) for k in drive_keys["backward"]) else 0.0)
        ds["angular"] += (incr if any(held(k) for k in drive_keys["left"]) else 0.0) \
                       - (incr if any(held(k) for k in drive_keys["right"]) else 0.0)
        ds["linear"]  = max(-1.0, min(ds["linear"],  1.0))
        ds["angular"] = max(-1.0, min(ds["angular"], 1.0))

        if any(held(k) for k in drive_keys.get("stop", [])):
            # Ramp back to zero at the same rate as the accel
            # ramp (ramp_rate) instead of snapping instantly —
            # avoids a velocity discontinuity at stop, the same
            # kind of instant-stop artifact investigated for the
            # scripted test scenario (see
            # data/arm_swing_diagnostics/rampstop_*).
            if ds["linear"] > 0:
                ds["linear"] = max(0.0, ds["linear"] - incr)
            else:
                ds["linear"] = min(0.0, ds["linear"] + incr)
            if ds["angular"] > 0:
                ds["angular"] = max(0.0, ds["angular"] - incr)
            else:
                ds["angular"] = min(0.0, ds["angular"] + incr)

        # Convert normalized commands to velocities
        lin_vel = ds["linear"] * max_lin_vel
        ang_vel = ds["angular"] * max_ang_vel
        moving = ds["linear"] != 0.0 or ds["angular"] != 0.0
        if moving or state["was_moving"] or drive_key_down:     # the zero that ends a ramp is emitted once
            cmds.append({"mode": "base", "twist": (lin_vel, ang_vel)})
        state["was_moving"] = moving

        # --- Pedestal lift: Page Up raises, Page Down lowers ---
        direction = int(held(ped_keys["up"])) - int(held(ped_keys["down"]))
        if direction:
            h = np.clip(applied["pedestal"] + direction * ped_step, ped_lo, ped_hi)
            cmds.append({"mode": "pedestal", "height": float(h)})

        # --- Manual arm / gripper jogging: one fixed key pair per joint ---
        arm_targets, grip = {}, {}
        for side, pairs in jog_keymap.items():
            for idx, (k_plus, k_minus) in enumerate(pairs):
                d = int(held(k_plus)) - int(held(k_minus))
                if d == 0:
                    continue
                ids, (lo, hi), speed = jog_tables[side][idx]
                step_ = speed * dt
                if idx == GRIP_IDX:
                    grip[side] = float(np.clip(applied["gripper"][side] + d * step_, lo, hi))
                else:
                    q = arm_targets.setdefault(side, list(applied["arm_targets"][side]))
                    q[idx] = float(np.clip(applied["arm_targets"][side][idx] + d * step_, lo, hi))
        if arm_targets or grip:
            cmd = {"mode": "arms"}
            if arm_targets:
                cmd["arm_targets"] = arm_targets
            if grip:
                cmd["gripper"] = grip
            cmds.append(cmd)

        # --- Camera neck: jog, frame the task points (F7), default aim (F8). Exempt from exclusivity. ---
        if nk is not None and neck_locked:
            pressed = frozenset(k for k in [k for pair in neck_pairs for k in pair] + [k_frame, k_home] if held(k))
            if pressed - state["prev_neck_locked_press"]:          # a neck key that was not down on the last tick: one line per press
                print("Neck keys are disabled while a replayable recording is being written (--record / --record-run).")
            state["prev_neck_locked_press"] = pressed
        elif nk is not None:
            goal = applied["neck_goal"]
            moved = {}
            for j, (k_plus, k_minus) in enumerate(neck_pairs):
                d = int(held(k_plus)) - int(held(k_minus))
                if d:
                    moved[nk["names"][j]] = float(np.clip(goal[nk["names"][j]] + d * neck_specs["jog_speed"] * dt, nk["lo"][j], nk["hi"][j]))
            if moved:
                cmds.append({"mode": "neck", "neck_targets": moved})
                state["neck_active_t"] = obs["time"]
            f7, f8 = held(k_frame), held(k_home)
            if f7 and not state["prev_f7"]:
                state["neck_active_t"] = obs["time"]
                points = points_fn(model, data) if points_fn is not None else None
                if not points:
                    print("F7: no task loaded in this scene, nothing to frame")
                else:
                    from src.neck_framing import frame_points, summarize
                    targets, report = frame_points(model, data, points, framing_cfg or {})
                    print("F7 " + summarize(report))
                    cmds.append({"mode": "neck", "neck_targets": targets})
            if f8 and not state["prev_f8"]:
                state["neck_active_t"] = obs["time"]
                cmds.append({"mode": "neck", "neck_targets": dict(zip(nk["names"], neck_specs["drive_pose"]))})
            state["prev_f7"], state["prev_f8"] = f7, f8
        return cmds

    return {"name": "keyboard", "step": step, "state": state}
